  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Changepeau-(Druide).html&quot; title=&quot;Changepeau&quot;&gt;Changepeau&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chanteur-Sylvestre-(Druide).html&quot; title=&quot;Chanteur sylvestre&quot;&gt;Chanteur sylvestre&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Elfe.html&quot; title=&quot;Les elfes&quot;&gt;Elfe&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chuchoteur-Sauvage-(Druide).html&quot; title=&quot;Chuchoteur sauvage&quot;&gt;Chuchoteur sauvage&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Croc-De-La-Nature-(Druide).html&quot; title=&quot;Croc de la nature&quot;&gt;Croc de la nature&lt;/a&gt; (MCA) &lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Aquatique-(Druide).html&quot; title=&quot;Druide aquatique&quot;&gt;Druide aquatique&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Arctique-(Druide).html&quot; title=&quot;Druide arctique&quot;&gt;Druide arctique&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-De-La-Jungle-(Druide).html&quot; title=&quot;Druide de la jungle&quot;&gt;Druide de la jungle&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Cavernes-(Druide).html&quot; title=&quot;Druide des cavernes&quot;&gt;Druide des cavernes&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-D&#233;serts-(Druide).html&quot; title=&quot;Druide des d&#233;serts&quot;&gt;Druide des d&#233;serts&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Marais-(Druide).html&quot; title=&quot;Druide des marais&quot;&gt;Druide des marais&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Montagnes-(Druide).html&quot; title=&quot;Druide des montagnes&quot;&gt;Druide des montagnes&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Ouragans-(Druide).html&quot; title=&quot;Druide des ouragans&quot;&gt;Druide des ouragans&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Plaines-(Druide).html&quot; title=&quot;Druide des plaines&quot;&gt;Druide des plaines&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Temp&#234;tes-(Druide).html&quot; title=&quot;Druide des temp&#234;tes&quot;&gt;Druide des temp&#234;tes&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Du-Ciel-(Druide).html&quot; title=&quot;Druide du ciel&quot;&gt;Druide du ciel&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Sylphe-(Race).html&quot; title=&quot;Les sylphes&quot;&gt;Sylphe&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-R&#233;incarn&#233;-(Druide).html&quot; title=&quot;Druide r&#233;incarn&#233;&quot;&gt;Druide r&#233;incarn&#233;&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Urbain-(Druide).html&quot; title=&quot;Druide urbain&quot;&gt;Druide urbain&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Enfant-De-La-Lune-(Druide).html&quot; title=&quot;Enfant de la lune&quot;&gt;Enfant de la lune&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Enfant-Sauvage-(Druide).html&quot; title=&quot;Enfant sauvage&quot;&gt;Enfant sauvage&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;Humain&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fl&#233;trisseur-(Druide).html&quot; title=&quot;Fl&#233;trisseur&quot;&gt;Fl&#233;trisseur&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gardien-Antique-(Druide).html&quot; title=&quot;Gardien antique&quot;&gt;Gardien antique&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Homme-Serpent.html&quot; title=&quot;Homme-serpent&quot;&gt;Homme-serpent&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;tamorphe-Sauvage-(Druide).html&quot; title=&quot;M&#233;tamorphe sauvage&quot;&gt;M&#233;tamorphe sauvage&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sage-Des-Menhirs-(Druide).html&quot; title=&quot;Sage des menhirs&quot;&gt;Sage des menhirs&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Seigneur-De-La-Meute-(Druide).html&quot; title=&quot;Seigneur de la meute&quot;&gt;Seigneur de la meute&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Surnaturaliste-(Druide).html&quot; title=&quot;Surnaturaliste&quot;&gt;Surnaturaliste&lt;/a&gt; (&lt;i&gt;OO&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Troll-Furieux-(Druide).html&quot; title=&quot;Troll furieux&quot;&gt;Troll furieux&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Troll.html&quot; title=&quot;Troll&quot;&gt;Troll&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Urushiol-(Druide).html&quot; title=&quot;Urushiol&quot;&gt;Urushiol&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;div style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Codex monstrueux/Monster Codex&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMC.gif&quot; style=&quot;opacity: 0.7&quot; /&gt;
&lt;/div&gt;&lt;b&gt;Cettte option est plus courante chez les &lt;a class=&quot;pagelink&quot; href=&quot;Homme-L&#233;zard.html&quot; title=&quot;Homme-l&#233;zard&quot;&gt;hommes-l&#233;zards&lt;/a&gt;.&lt;/b&gt;&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Les gardiens antiques r&#233;v&#232;rent la nature et tirent leurs pouvoirs de ses &#233;nergies divines mais ils prot&#232;gent aussi les coutumes, l’histoire et le savoir de leur tribu et de leur race. Ce sont des ambassadeurs et des protecteurs des traditions. Ils veillent au d&#233;veloppement de leur tribu et tiennent l’influence corruptrice de la civilisation en respect.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Armes antiques&lt;a class=&quot;headeranchor&quot; id=&quot;Armes_antiques_0&quot; href=&quot;#Armes_antiques_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un gardien antique ne peut pas manier d’armes essentiellement constitu&#233;es de m&#233;tal. Il est form&#233; au maniement du &lt;a class=&quot;pagelink&quot; href=&quot;Gourdin-(Arme).html&quot; title=&quot;Gourdin&quot;&gt;gourdin&lt;/a&gt;, des &lt;a class=&quot;unknownlink&quot; href=&quot;Dard-(Arme).html&quot; title=&quot;Pathfinder-RPG.dard (arme)&quot;&gt;dards&lt;/a&gt;, du &lt;a class=&quot;pagelink&quot; href=&quot;B&#226;ton-(Arme).html&quot; title=&quot;B&#226;ton&quot;&gt;b&#226;ton&lt;/a&gt;, de l&#39;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;pieu-(Arme).html&quot; title=&quot;&#201;pieu&quot;&gt;&#233;pieu&lt;/a&gt;, de la &lt;a class=&quot;pagelink&quot; href=&quot;Fronde-(Arme).html&quot; title=&quot;Fronde&quot;&gt;fronde&lt;/a&gt; et de la &lt;a class=&quot;pagelink&quot; href=&quot;Lance-(Arme).html&quot; title=&quot;Lance&quot;&gt;lance&lt;/a&gt;. Il est aussi form&#233; &#224; l’utilisation des armes naturelles (griffes, morsure etc.) de toutes les formes qu’il rev&#234;t via &lt;a class=&quot;pagelink&quot; href=&quot;Druide#Formeanimale.html&quot; title=&quot;Forme animale&quot;&gt;forme animale&lt;/a&gt;. S’il utilise une arme interdite, il ne peut plus lancer de sorts de druide.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Coutumes ancestrales (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Coutumes_ancestrales_Ext_1&quot; href=&quot;#Coutumes_ancestrales_Ext_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 3, le gardien antique augmente ses vitesses d’escalade, de vol et de nage (obtenues naturellement ou via son pouvoir de &lt;a class=&quot;pagelink&quot; href=&quot;Druide#Formeanimale.html&quot; title=&quot;Forme animale&quot;&gt;forme animale&lt;/a&gt;) de 9 m&#232;tres. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#ABSENCEDETRACES&quot; title=&quot;Le druide&quot;&gt;absence de traces&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#DEPLACEMENTFACILITE&quot; title=&quot;Le druide&quot;&gt;d&#233;placement facilit&#233;&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;D&#233;faire l’artisanat (Mag)&lt;a class=&quot;headeranchor&quot; id=&quot;D&#233;faire_l’artisanat_Mag_2&quot; href=&quot;#D&#233;faire_l’artisanat_Mag_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 13, le gardien antique apprend &#224; d&#233;composer un objet non vivant en ses composantes brutes. Cela fonctionne comme &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;tamorphose-Universelle.html&quot; title=&quot;M&#233;tamorphose universelle&quot;&gt;m&#233;tamorphose universelle&lt;/a&gt;&lt;/i&gt; mais fonctionne uniquement sur des objets, magiques ou non, non vivants. La dur&#233;e de l’effet est toujours permanente. Contrairement &#224; la &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;tamorphose-Universelle.html&quot; title=&quot;M&#233;tamorphose universelle&quot;&gt;m&#233;tamorphose universelle&lt;/a&gt;&lt;/i&gt;, ce pouvoir ne peut pas servir &#224; imiter les effets d’un autre sort. Un objet soumis &#224; cet effet a droit &#224; un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; = 10 + 1/2 niveau du druide + son modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Sagesse.html&quot; title=&quot;La Sagesse&quot;&gt;Sagesse&lt;/a&gt;). Les objets magiques re&#231;oivent un bonus de circonstance au &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; de +1 par tranche de 5 000 po de valeur. Chaque jour, le gardien antique peut utiliser ce pouvoir un nombre de fois &#233;gal &#224; son modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Sagesse.html&quot; title=&quot;La Sagesse&quot;&gt;Sagesse&lt;/a&gt;. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#MILLEVISAGES&quot; title=&quot;Le druide&quot;&gt;mille visages&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Dissipation de l’hostilit&#233; (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Dissipation_de_l’hostilit&#233;_Sur_3&quot; href=&quot;#Dissipation_de_l’hostilit&#233;_Sur_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un gardien antique ne gagne pas de sorts spontan&#233;s au niveau 1, &#224; la place, au niveau 3, il peut canaliser l’&#233;nergie stock&#233;e pour un sort et la changer en un sort capable de dissiper les pens&#233;es hostiles et les &#233;motions les plus puissantes. Il peut &#171; perdre &#187; un sort pr&#233;par&#233; afin de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Apaisement-Des-&#201;motions.html&quot; title=&quot;Apaisement des &#233;motions&quot;&gt;apaisement des &#233;motions&lt;/a&gt;&lt;/i&gt;. Le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; du &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; contre ce sort, quand il est lanc&#233; ainsi, est de 10 + 1/2 niveau du druide + son modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Sagesse.html&quot; title=&quot;La Sagesse&quot;&gt;Sagesse&lt;/a&gt;. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#INCANTATIONSPONTANEE&quot; title=&quot;Le druide&quot;&gt;incantation spontan&#233;e&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Irr&#233;prochable (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Irr&#233;prochable_Ext_4&quot; href=&quot;#Irr&#233;prochable_Ext_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 4, le gardien antique gagne un bonus de +4 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les enchantements. Ce pouvoir remplace celui de &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#RESISTANCEALAPPELDELANATURE&quot; title=&quot;Le druide&quot;&gt;r&#233;sistance &#224; l’appel de la nature&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Pacte avec la communaut&#233; (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Pacte_avec_la_communaut&#233;_Ext_5&quot; href=&quot;#Pacte_avec_la_communaut&#233;_Ext_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 1, le gardien antique doit choisir le pouvoir de &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#PACTEAVECLANATURE&quot; title=&quot;Le druide&quot;&gt;pacte avec la nature : domaine&lt;/a&gt; et choisir son domaine parmi les suivants : &lt;a class=&quot;pagelink&quot; href=&quot;Domaine-De-La-Communaut&#233;.html&quot; title=&quot;Domaine de la Communaut&#233;&quot;&gt;Communaut&#233;&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Domaine-De-La-Connaissance.html&quot; title=&quot;Domaine de la Connaissance&quot;&gt;Connaissance&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Domaine-De-La-Gu&#233;rison.html&quot; title=&quot;Domaine de la Gu&#233;rison&quot;&gt;Gu&#233;rison&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Domaine-De-La-Protection.html&quot; title=&quot;Domaine de la Protection&quot;&gt;Protection&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Domaine-Du-Repos.html&quot; title=&quot;Domaine du Repos&quot;&gt;Repos&lt;/a&gt;. Ce pouvoir modifie &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#PACTEAVECLANATURE&quot; title=&quot;Le druide&quot;&gt;pacte avec la nature&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Patience de la nature (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Patience_de_la_nature_Ext_6&quot; href=&quot;#Patience_de_la_nature_Ext_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Le gardien antique ne gagne pas &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#EMPATHIESAUVAGE&quot; title=&quot;Le druide&quot;&gt;empathie sauvage&lt;/a&gt; au niveau 1. En revanche, au niveau 2, il ajoute &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentation.html&quot; title=&quot;Repr&#233;sentation&quot;&gt;Repr&#233;sentation&lt;/a&gt; (d&#233;clamation) et &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt; &#224; ses comp&#233;tences de classe et obtient un bonus d’intuition &#233;gal &#224; la moiti&#233; de son niveau de druide &#224; ces tests. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#EMPATHIESAUVAGE&quot; title=&quot;Le druide&quot;&gt;empathie sauvage&lt;/a&gt;.
